sp_widget.client_script:
api.controller = function($scope, $window) {

    var c = this;


    /*
     * =====================================================
     * SEARCH
     * =====================================================
     */

    c.search = "";


    /*
     * =====================================================
     * ROLE FILTER
     * =====================================================
     */

    c.rolePeriod = "season";


    /*
     * =====================================================
     * REFRESH DASHBOARD
     * =====================================================
     */

    c.refreshDashboard = function() {

        c.data = {};

        c.server.update();

    };


    /*
     * =====================================================
     * VIEW CANDIDATE
     * =====================================================
     */

    c.viewCandidate = function(candidate) {

        if (!candidate || !candidate.sys_id) {
            return;
        }

        /*
         * Change this page ID later when
         * Candidate Details page is created.
         */

        $window.location.href =
            "?id=campus360_recruiter_candidate_details" +
            "&sys_id=" +
            candidate.sys_id;

    };


    /*
     * =====================================================
     * SEARCH CANDIDATES
     * =====================================================
     */

    c.searchCandidates = function(candidate) {

        if (!c.search) {
            return true;
        }

        var searchText =
            c.search.toLowerCase();

        var name =
            (candidate.name || "")
            .toLowerCase();

        var role =
            (candidate.role || "")
            .toLowerCase();

        var status =
            (candidate.status || "")
            .toLowerCase();

        return (
            name.indexOf(searchText) >= 0 ||
            role.indexOf(searchText) >= 0 ||
            status.indexOf(searchText) >= 0
        );

    };


    /*
     * =====================================================
     * INITIALIZE
     * =====================================================
     */

    $scope.$watch(
        function() {
            return c.data;
        },
        function(newData) {

            if (!newData) {
                return;
            }

            /*
             * Data is already prepared
             * by Server Script.
             */

        },
        true
    );

};

sp_widget.css:
/* =========================================================
CAMPUS360 RECRUITER DASHBOARD
========================================================= */

.campus360-recruiter {
min-height: 100vh;
background: #f5f7fb;
color: #172033;
font-family: "Inter", "Segoe UI", Arial, sans-serif;
display: flex;
}

/* =========================================================
SIDEBAR
========================================================= */

.recruiter-sidebar {
width: 250px;
min-height: 100vh;
background: #101b3d;
color: #ffffff;
padding: 22px 16px;
display: flex;
flex-direction: column;
box-sizing: border-box;
}

.sidebar-brand {
display: flex;
align-items: center;
gap: 12px;
padding: 4px 8px 24px;
}

.brand-mark {
width: 40px;
height: 40px;
border-radius: 11px;
background: #ffffff;
color: #3155d9;
display: flex;
align-items: center;
justify-content: center;
font-size: 22px;
font-weight: 800;
}

.brand-name {
font-size: 18px;
font-weight: 800;
}

.brand-subtitle {
font-size: 11px;
color: #aeb9d8;
margin-top: 2px;
}

/* COMPANY PROFILE */

.company-profile {
background: rgba(255,255,255,0.08);
border-radius: 12px;
padding: 12px;
display: flex;
align-items: center;
gap: 10px;
margin-bottom: 22px;
}

.company-avatar,
.top-avatar,
.candidate-avatar {
display: flex;
align-items: center;
justify-content: center;
border-radius: 50%;
font-weight: 700;
}

.company-avatar {
width: 38px;
height: 38px;
background: #536dfe;
color: white;
font-size: 13px;
}

.company-name {
font-size: 13px;
font-weight: 700;
}

.recruiter-name {
font-size: 11px;
color: #aeb9d8;
margin-top: 3px;
}

/* NAVIGATION */

.recruiter-nav {
flex: 1;
}

.nav-section-title {
font-size: 10px;
font-weight: 700;
color: #7e8db7;
letter-spacing: 1px;
padding: 13px 10px 7px;
}

.nav-item {
display: flex;
align-items: center;
gap: 10px;
color: #c6cee4;
text-decoration: none;
padding: 10px 11px;
border-radius: 8px;
margin-bottom: 3px;
font-size: 13px;
transition: all 0.2s ease;
}

.nav-item {
background: rgba(255,255,255,0.08);
color: #ffffff;
text-decoration: none;
}

.nav-item.active {
background: #536dfe;
color: #ffffff;
}

.nav-icon {
width: 20px;
text-align: center;
font-size: 15px;
}

.nav-count {
margin-left: auto;
background: #ef5350;
color: white;
border-radius: 20px;
padding: 2px 7px;
font-size: 10px;
}

/* SIDEBAR FOOTER */

.sidebar-footer {
border-top: 1px solid rgba(255,255,255,0.1);
padding: 16px 8px 2px;
}

.footer-title {
font-size: 12px;
font-weight: 700;
}

.footer-subtitle {
color: #8290b8;
font-size: 10px;
margin-top: 4px;
}

/* =========================================================
MAIN
========================================================= */

.recruiter-main {
flex: 1;
min-width: 0;
}

/* =========================================================
TOPBAR
========================================================= */

.recruiter-topbar {
height: 68px;
background: #ffffff;
border-bottom: 1px solid #e8ebf2;
display: flex;
align-items: center;
justify-content: space-between;
padding: 0 30px;
box-sizing: border-box;
}

.topbar-search {
width: 390px;
height: 38px;
background: #f5f7fb;
border: 1px solid #e7eaf1;
border-radius: 8px;
display: flex;
align-items: center;
padding: 0 12px;
}

.search-icon {
color: #8993a8;
margin-right: 8px;
font-size: 19px;
}

.topbar-search input {
border: none;
outline: none;
background: transparent;
width: 100%;
font-size: 12px;
color: #27324a;
}

.topbar-actions {
display: flex;
align-items: center;
gap: 9px;
}

.top-icon {
width: 35px;
height: 35px;
border: 1px solid #e4e8f0;
background: white;
border-radius: 8px;
color: #65708a;
cursor: pointer;
}

.top-icon {
background: #f5f7fb;
}

.top-profile {
display: flex;
align-items: center;
gap: 9px;
margin-left: 8px;
padding-left: 14px;
border-left: 1px solid #e5e8ef;
}

.top-avatar {
width: 34px;
height: 34px;
background: #e9edff;
color: #3e57c9;
font-size: 12px;
}

.top-profile-info {
display: flex;
flex-direction: column;
}

.top-profile-info strong {
font-size: 12px;
}

.top-profile-info span {
color: #8a94a8;
font-size: 10px;
margin-top: 2px;
}

/* =========================================================
DASHBOARD CONTENT
========================================================= */

.recruiter-dashboard {
padding: 28px 30px;
max-width: 1600px;
margin: auto;
}

.dashboard-header {
display: flex;
align-items: flex-start;
justify-content: space-between;
margin-bottom: 25px;
}

.eyebrow,
.card-eyebrow {
font-size: 9px;
font-weight: 800;
letter-spacing: 1.1px;
color: #6273d7;
}

.dashboard-header h1 {
margin: 5px 0 7px;
font-size: 27px;
font-weight: 750;
color: #15203b;
}

.dashboard-header p {
margin: 0;
color: #78839a;
font-size: 12px;
max-width: 680px;
}

.company-context {
background: #ffffff;
border: 1px solid #e7eaf1;
border-radius: 10px;
padding: 11px 17px;
text-align: right;
}

.company-context span {
display: block;
font-size: 8px;
color: #8993a8;
letter-spacing: 1px;
}

.company-context strong {
display: block;
margin-top: 3px;
font-size: 13px;
}

/* =========================================================
KPI CARDS
========================================================= */

.kpi-grid {
display: grid;
grid-template-columns: repeat(5, 1fr);
gap: 14px;
margin-bottom: 18px;
}

.kpi-card {
background: #ffffff;
border: 1px solid #e7eaf1;
border-radius: 12px;
padding: 17px;
min-height: 122px;
box-sizing: border-box;
text-decoration: none;
color: inherit;
transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.kpi-card {
transform: translateY(-2px);
box-shadow: 0 8px 22px rgba(30, 48, 90, 0.08);
text-decoration: none;
}

.kpi-top {
display: flex;
justify-content: space-between;
align-items: center;
}

.kpi-label {
font-size: 11px;
color: #78839a;
font-weight: 600;
}

.kpi-icon {
width: 30px;
height: 30px;
border-radius: 8px;
display: flex;
justify-content: center;
align-items: center;
font-size: 14px;
}

.kpi-blue .kpi-icon {
background: #eaf0ff;
color: #4967dc;
}

.kpi-green .kpi-icon {
background: #e8f8ef;
color: #2d9a5b;
}

.kpi-purple .kpi-icon {
background: #f0eaff;
color: #7655d8;
}

.kpi-orange .kpi-icon {
background: #fff2e4;
color: #e28a32;
}

.kpi-value {
font-size: 28px;
font-weight: 800;
margin-top: 12px;
color: #17213b;
}

.kpi-bottom {
display: flex;
justify-content: space-between;
margin-top: 5px;
color: #929bad;
font-size: 9px;
}

.kpi-link {
color: #5268d6;
font-weight: 700;
}

/* =========================================================
CARDS
========================================================= */

.dashboard-grid {
display: grid;
grid-template-columns: 1.45fr 1fr;
gap: 18px;
margin-bottom: 18px;
}

.lower-grid {
display: grid;
grid-template-columns: 1.45fr 1fr;
gap: 18px;
margin-bottom: 18px;
}

.bottom-grid {
display: grid;
grid-template-columns: 1.45fr 1fr;
gap: 18px;
}

.dashboard-card {
background: #ffffff;
border: 1px solid #e7eaf1;
border-radius: 12px;
padding: 20px;
box-sizing: border-box;
}

.card-header {
display: flex;
justify-content: space-between;
align-items: flex-start;
margin-bottom: 18px;
}

.card-header h2 {
margin: 4px 0 0;
font-size: 15px;
color: #1a2540;
}

.card-header select {
border: 1px solid #e3e7ef;
background: white;
border-radius: 6px;
padding: 6px 9px;
font-size: 10px;
color: #69748a;
}

.card-header a {
font-size: 10px;
color: #5268d6;
text-decoration: none;
font-weight: 700;
}

/* =========================================================
APPLICATION ROLE CHART
========================================================= */

.role-chart {
height: 205px;
display: flex;
align-items: flex-end;
justify-content: space-around;
gap: 18px;
padding: 10px 10px 0;
border-bottom: 1px solid #edf0f5;
}

.role-bar {
flex: 1;
max-width: 90px;
height: 100%;
display: flex;
flex-direction: column;
align-items: center;
justify-content: flex-end;
}

.bar-value {
font-size: 10px;
font-weight: 700;
color: #4f5e7e;
margin-bottom: 5px;
}

.bar {
width: 42px;
max-height: 145px;
min-height: 4px;
background: #6378e8;
border-radius: 6px 6px 0 0;
}

.bar-label {
margin-top: 8px;
color: #7e8799;
font-size: 9px;
text-align: center;
max-width: 75px;
overflow: hidden;
text-overflow: ellipsis;
white-space: nowrap;
}

/* =========================================================
STATUS
========================================================= */

.status-content {
display: flex;
align-items: center;
gap: 35px;
min-height: 205px;
}

.status-circle {
width: 135px;
height: 135px;
border-radius: 50%;
border: 14px solid #e9edff;
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
flex-shrink: 0;
}

.status-total {
font-size: 25px;
font-weight: 800;
}

.status-label {
font-size: 9px;
color: #8a94a7;
margin-top: 2px;
}

.status-list {
flex: 1;
}

.status-row {
display: flex;
align-items: center;
gap: 7px;
font-size: 10px;
margin-bottom: 13px;
color: #5e687c;
}

.status-row strong {
margin-left: auto;
color: #1e2942;
}

.status-row small {
color: #9aa2b2;
}

.status-dot {
width: 8px;
height: 8px;
border-radius: 50%;
}

.status-pending {
background: #f4b740;
}

.status-shortlisted {
background: #5471e2;
}

.status-rejected {
background: #e95c63;
}

.status-selected {
background: #42a66b;
}

.status-other {
background: #9aa2b2;
}

/* =========================================================
CANDIDATE TABLE
========================================================= */

.candidate-table {
width: 100%;
}

.table-header,
.candidate-row {
display: grid;
grid-template-columns: 1.4fr 1.1fr 1.1fr .8fr 1fr .55fr;
gap: 12px;
align-items: center;
}

.table-header {
padding: 9px 0;
border-bottom: 1px solid #edf0f4;
color: #9aa2b3;
font-size: 9px;
font-weight: 700;
}

.candidate-row {
padding: 12px 0;
border-bottom: 1px solid #f0f2f6;
font-size: 10px;
color: #606b81;
}

.candidate-name {
display: flex;
align-items: center;
gap: 8px;
color: #26314a;
font-weight: 650;
}

.candidate-avatar {
width: 29px;
height: 29px;
background: #edf0ff;
color: #4d62ca;
font-size: 9px;
}

.skill-match {
display: flex;
align-items: center;
gap: 7px;
}

.skill-bar {
width: 45px;
height: 5px;
background: #e9ecf2;
border-radius: 10px;
overflow: hidden;
}

.skill-fill {
height: 100%;
background: #536ddd;
border-radius: 10px;
}

.skill-match span {
font-size: 9px;
font-weight: 700;
}

.status-badge {
display: inline-block;
border-radius: 20px;
padding: 4px 7px;
font-size: 8px;
font-weight: 700;
}

.badge-pending {
background: #fff4d9;
color: #b27a10;
}

.badge-shortlisted {
background: #e9edff;
color: #4c62c9;
}

.badge-rejected {
background: #ffe9ea;
color: #c34e56;
}

.badge-selected {
background: #e6f7ed;
color: #278051;
}

.badge-other {
background: #eef0f4;
color: #697286;
}

.view-button {
border: none;
background: #eef1ff;
color: #5066cf;
padding: 5px 8px;
border-radius: 5px;
font-size: 9px;
cursor: pointer;
}

.view-button {
background: #dfe5ff;
}

/* =========================================================
INTERVIEWS
========================================================= */

.interview-list {
display: flex;
flex-direction: column;
}

.interview-item {
display: flex;
align-items: center;
gap: 11px;
padding: 11px 0;
border-bottom: 1px solid #eff1f5;
}

.interview-date {
width: 42px;
height: 42px;
border-radius: 8px;
background: #eef1ff;
color: #4f63c9;
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
}

.interview-date strong {
font-size: 15px;
}

.interview-date span {
font-size: 8px;
text-transform: uppercase;
}

.interview-details {
display: flex;
flex-direction: column;
flex: 1;
}

.interview-details strong {
font-size: 10px;
color: #29344e;
}

.interview-details span {
font-size: 9px;
color: #7c879b;
margin-top: 2px;
}

.interview-details small {
font-size: 8px;
color: #9ba3b2;
margin-top: 3px;
}

.interview-status {
font-size: 8px;
color: #4f63c9;
background: #eef1ff;
padding: 4px 6px;
border-radius: 10px;
}

/* =========================================================
QUICK ACTIONS
========================================================= */

.quick-actions {
display: grid;
grid-template-columns: 1fr 1fr;
gap: 10px;
}

.quick-action {
border: 1px solid #e9ecf2;
border-radius: 9px;
padding: 13px;
text-decoration: none;
color: inherit;
display: flex;
flex-direction: column;
transition: 0.2s;
}

.quick-action {
border-color: #bfc9f5;
background: #fafbff;
text-decoration: none;
}

.quick-action > span {
width: 28px;
height: 28px;
display: flex;
align-items: center;
justify-content: center;
background: #eef1ff;
color: #5066d0;
border-radius: 7px;
margin-bottom: 8px;
}

.quick-action strong {
font-size: 10px;
color: #29344e;
}

.quick-action small {
color: #8a94a7;
font-size: 8px;
margin-top: 4px;
}

/* =========================================================
ACTIVITY
========================================================= */

.activity-list {
display: flex;
flex-direction: column;
}

.activity-item {
display: flex;
gap: 10px;
align-items: center;
padding: 10px 0;
border-bottom: 1px solid #eff1f5;
}

.activity-icon {
width: 30px;
height: 30px;
border-radius: 7px;
background: #eef1ff;
color: #5268d3;
display: flex;
align-items: center;
justify-content: center;
font-size: 12px;
}

.activity-item > div {
display: flex;
flex-direction: column;
}

.activity-item strong {
font-size: 9px;
color: #313b52;
}

.activity-item span {
font-size: 8px;
color: #929bad;
margin-top: 3px;
}

/* =========================================================
FOOTER
========================================================= */

.dashboard-footer {
display: flex;
justify-content: space-between;
align-items: center;
padding: 18px 2px 5px;
color: #929bad;
font-size: 9px;
}

.dashboard-footer button {
border: none;
background: transparent;
color: #5368d1;
font-size: 9px;
cursor: pointer;
}

/* =========================================================
RESPONSIVE
========================================================= */

@media (max-width: 1200px) {

.kpi-grid {
    grid-template-columns: repeat(3, 1fr);
}

.dashboard-grid,
.lower-grid,
.bottom-grid {
    grid-template-columns: 1fr;
}

}

@media (max-width: 850px) {

.recruiter-sidebar {
    width: 70px;
    padding: 15px 8px;
}

.brand-name,
.brand-subtitle,
.company-profile > div:last-child,
.nav-section-title,
.nav-item span:not(.nav-icon),
.sidebar-footer {
    display: none;
}

.sidebar-brand {
    justify-content: center;
}

.company-profile {
    justify-content: center;
}

.nav-item {
    justify-content: center;
}

.nav-count {
    display: none;
}

.recruiter-topbar {
    padding: 0 15px;
}

.topbar-search {
    width: 230px;
}

.recruiter-dashboard {
    padding: 20px 15px;
}

.dashboard-header {
    flex-direction: column;
    gap: 15px;
}

.kpi-grid {
    grid-template-columns: repeat(2, 1fr);
}

}

@media (max-width: 600px) {

.kpi-grid {
    grid-template-columns: 1fr;
}

.topbar-search {
    width: 160px;
}

.top-profile-info {
    display: none;
}

.table-header {
    display: none;
}

.candidate-row {
    grid-template-columns: 1fr;
    gap: 6px;
    padding: 15px 0;
}

.status-content {
    flex-direction: column;
    justify-content: center;
}

.quick-actions {
    grid-template-columns: 1fr;
}

}

sp_widget.script:
(function() {

    data.kpis = {
        applications: 0,
        shortlisted: 0,
        interviews: 0,
        offers: 0,
        inProgress: 0
    };

    data.recruiter = {
        name: gs.getUserDisplayName() || "Recruiter",
        company: "Campus Recruiter",
        initials: "CR"
    };

    data.applicationsByRole = [];
    data.applicationStatus = [];
    data.topCandidates = [];
    data.upcomingInterviews = [];
    data.recentActivity = [];


    /*
     * =====================================================
     * 1. IDENTIFY RECRUITER / COMPANY
     * =====================================================
     */

    var currentEmail = gs.getUser().getEmail();

	var companySysId = "";

	var companyGR = new GlideRecord(
		"x_snc_campus360_company_master"
	);

	companyGR.addQuery("recruiter_email", currentEmail);
	companyGR.setLimit(1);
	companyGR.query();

	if (companyGR.next()) {

		companySysId =
			companyGR.getUniqueValue();

        data.recruiter.company =
            companyGR.getValue("company_name") ||
            "Campus Recruiter";

        data.recruiter.name =
            companyGR.getValue("recruiter_name") ||
            gs.getUserDisplayName();

    }


    /*
     * INITIALS
     */

    var nameParts = data.recruiter.name.split(" ");

    if (nameParts.length >= 2) {

        data.recruiter.initials =
            nameParts[0].substring(0, 1) +
            nameParts[nameParts.length - 1].substring(0, 1);

    } else {

        data.recruiter.initials =
            data.recruiter.name.substring(0, 2);

    }


    /*
     * =====================================================
     * 2. TOTAL APPLICATIONS
     * =====================================================
     */

    var appGR = new GlideRecord(
		"x_snc_campus360_student_application"
	);

	appGR.addQuery(
		"opportunity.company",
		companySysId
	);

	appGR.query();

    while (appGR.next()) {

        data.kpis.applications++;

        var appStatus =
            (appGR.getValue("application_status") || "")
            .toLowerCase();

        if (
            appStatus.indexOf("short") >= 0 ||
            appGR.getValue("shortlisted") == "true"
        ) {

            data.kpis.shortlisted++;

        }


        if (
            appStatus.indexOf("pending") >= 0 ||
            appStatus.indexOf("progress") >= 0 ||
            appStatus.indexOf("review") >= 0
        ) {

            data.kpis.inProgress++;

        }

    }


    /*
     * =====================================================
     * 3. INTERVIEWS
     * =====================================================
     */

    var interviewGR = new GlideRecord(
        "x_snc_campus360_recruiter_interview"
    );

    interviewGR.addQuery(
        "interview_date",
        ">=",
        gs.beginningOfToday()
    );

    interviewGR.query();

    while (interviewGR.next()) {

        data.kpis.interviews++;

    }


    /*
	* =====================================================
	* 4. OFFERS / PLACEMENT OUTCOMES
	* =====================================================
	*/

	var outcomeGR = new GlideRecord(
		"x_snc_campus360_placement_outcome"
	);

	outcomeGR.query();

	while (outcomeGR.next()) {

		var outcomeStatus =
			(
				outcomeGR.getValue("outcome_type") ||
				""
			).toLowerCase();

		if (
			outcomeStatus.indexOf("offer") >= 0 ||
			outcomeStatus.indexOf("selected") >= 0 ||
			outcomeStatus.indexOf("placed") >= 0
		) {

			data.kpis.offers++;

		}

	}


    /*
     * =====================================================
     * 5. APPLICATION STATUS
     * =====================================================
     */

    var statusMap = {};

    var statusGR = new GlideRecord(
		"x_snc_campus360_student_application"
	);

	statusGR.addQuery(
		"opportunity.company",
		companySysId
	);

	statusGR.query();

    while (statusGR.next()) {

        var status =
            statusGR.getValue("application_status") ||
            "Other";

        if (!statusMap[status]) {
            statusMap[status] = 0;
        }

        statusMap[status]++;

    }


    var totalApplications = data.kpis.applications;

    for (var statusName in statusMap) {

        var statusClass = "other";

        var lowerStatus =
            statusName.toLowerCase();

        if (lowerStatus.indexOf("pending") >= 0) {
            statusClass = "pending";
        } else if (lowerStatus.indexOf("short") >= 0) {
            statusClass = "shortlisted";
        } else if (lowerStatus.indexOf("reject") >= 0) {
            statusClass = "rejected";
        } else if (
            lowerStatus.indexOf("select") >= 0 ||
            lowerStatus.indexOf("offer") >= 0
        ) {
            statusClass = "selected";
        }

        data.applicationStatus.push({
            label: statusName,
            count: statusMap[statusName],
            percent: totalApplications ?
                Math.round(
                    (statusMap[statusName] /
                    totalApplications) * 100
                ) : 0,
            class: statusClass
        });

    }


    /*
     * =====================================================
     * 6. APPLICATIONS BY ROLE
     * =====================================================
     */

    var roleMap = {};

	var roleGR = new GlideRecord(
		"x_snc_campus360_student_application"
	);

	roleGR.addQuery(
		"opportunity.company",
		companySysId
	);

	roleGR.query();

    while (roleGR.next()) {

        var opportunity =
            roleGR.getValue("opportunity");

        if (!opportunity) {
            continue;
        }

        var opportunityGR = new GlideRecord(
            "x_snc_campus360_placement_opportunity"
        );

        if (opportunityGR.get(opportunity)) {

            var role =
                opportunityGR.getValue("opportunity_title") ||
                "Other";

            if (!roleMap[role]) {
                roleMap[role] = 0;
            }

            roleMap[role]++;

        }

    }


    var maxRoleCount = 1;

    for (var roleName in roleMap) {

        if (roleMap[roleName] > maxRoleCount) {
            maxRoleCount = roleMap[roleName];
        }

    }


    for (var roleKey in roleMap) {

        data.applicationsByRole.push({

            role: roleKey,

            count: roleMap[roleKey],

            height:
                Math.max(
                    10,
                    Math.round(
                        (roleMap[roleKey] /
                        maxRoleCount) * 145
                    )
                )

        });

    }


    /*
     * =====================================================
     * 7. TOP CANDIDATES
     * =====================================================
     */

    var candidateGR = new GlideRecord(
		"x_snc_campus360_student_application"
	);

	candidateGR.addQuery(
		"opportunity.company",
		companySysId
	);

	candidateGR.orderByDesc("ai_match_score");
	candidateGR.setLimit(8);
	candidateGR.query();

    while (candidateGR.next()) {

        var studentID =
            candidateGR.getValue("student");

        var studentName = "Student";

        var studentGR = new GlideRecord(
            "x_snc_campus360_student_master"
        );

        if (
            studentID &&
            studentGR.get(studentID)
        ) {

            studentName =
                studentGR.getValue("student_name") ||
                "Student";

        }


        var candidateRole = "Candidate";

        var oppID =
            candidateGR.getValue("opportunity");

        if (oppID) {

            var oppGR = new GlideRecord(
                "x_snc_campus360_placement_opportunity"
            );

            if (oppGR.get(oppID)) {

                candidateRole =
                    oppGR.getValue("opportunity_title") ||
                    "Candidate";

            }

        }


        var matchScore =
            parseInt(
                candidateGR.getValue("ai_match_score"),
                10
            ) || 0;


        var candidateStatus =
            candidateGR.getValue(
                "application_status"
            ) || "Pending";


        var statusClass = "other";

        var lowerCandidateStatus =
            candidateStatus.toLowerCase();

        if (
            lowerCandidateStatus.indexOf("short") >= 0
        ) {
            statusClass = "shortlisted";
        } else if (
            lowerCandidateStatus.indexOf("reject") >= 0
        ) {
            statusClass = "rejected";
        } else if (
            lowerCandidateStatus.indexOf("select") >= 0 ||
            lowerCandidateStatus.indexOf("offer") >= 0
        ) {
            statusClass = "selected";
        } else if (
            lowerCandidateStatus.indexOf("pending") >= 0
        ) {
            statusClass = "pending";
        }


        var candidateParts =
            studentName.split(" ");

        var initials = "";

        if (candidateParts.length >= 2) {

            initials =
                candidateParts[0].substring(0, 1) +
                candidateParts[
                    candidateParts.length - 1
                ].substring(0, 1);

        } else {

            initials =
                studentName.substring(0, 2);

        }


        data.topCandidates.push({

            sys_id:
                candidateGR.getUniqueValue(),

            name:
                studentName,

            initials:
                initials.toUpperCase(),

            role:
                candidateRole,

            match:
                matchScore,

            status:
                candidateStatus,

            statusClass:
                statusClass,

            stage:
                candidateStatus

        });

    }


    /*
     * =====================================================
     * 8. UPCOMING INTERVIEWS
     * =====================================================
     */

    var upcomingGR = new GlideRecord(
		"x_snc_campus360_recruiter_interview"
	);

	upcomingGR.addQuery(
		"opportunity.company",
		companySysId
	);

	upcomingGR.addQuery(
		"interview_date",
		">=",
		gs.beginningOfToday()
	);

	upcomingGR.orderBy("interview_date");
	upcomingGR.setLimit(6);
	upcomingGR.query();

    while (upcomingGR.next()) {

        var interviewStudent =
            upcomingGR.getValue("student");

        var interviewStudentName =
            "Student";

        var isGR = new GlideRecord(
            "x_snc_campus360_student_master"
        );

        if (
            interviewStudent &&
            isGR.get(interviewStudent)
        ) {

            interviewStudentName =
                isGR.getValue("student_name") ||
                "Student";

        }


        var interviewDate =
            upcomingGR.getValue(
                "interview_date"
            );

        var gd =
            new GlideDateTime(interviewDate);


        var day =
            gd.getDayOfMonthLocalTime();

        var month =
            gd.getMonthLocalTime();


        var monthNames = [
            "Jan", "Feb", "Mar", "Apr",
            "May", "Jun", "Jul", "Aug",
            "Sep", "Oct", "Nov", "Dec"
        ];


        data.upcomingInterviews.push({

            student:
                interviewStudentName,

            role:
                upcomingGR.getValue(
                    "interview_type"
                ) || "Interview",

            day:
                day,

            month:
                monthNames[month - 1],

            time:
                upcomingGR.getDisplayValue(
                    "start_time"
                ),

            status:
                upcomingGR.getValue(
                    "interview_status"
                ) || "Scheduled"

        });

    }


    /*
     * =====================================================
     * 9. RECENT ACTIVITY
     * =====================================================
     */

    var recentAppGR = new GlideRecord(
        "x_snc_campus360_student_application"
    );

    recentAppGR.orderByDesc("sys_updated_on");
    recentAppGR.setLimit(5);
    recentAppGR.query();

    while (recentAppGR.next()) {

        var activityStatus =
            recentAppGR.getValue(
                "application_status"
            ) || "Application Updated";


        data.recentActivity.push({

            title:
                "Application " +
                activityStatus,

            time:
                recentAppGR.getDisplayValue(
                    "sys_updated_on"
                ),

            type:
                "application",

            icon:
                "•"

        });

    }


    /*
     * =====================================================
     * 10. FALLBACK ACTIVITY
     * =====================================================
     */

    if (data.recentActivity.length === 0) {

        data.recentActivity.push({

            title:
                "No recent recruitment activity",

            time:
                "Waiting for activity",

            type:
                "application",

            icon:
                "•"

        });

    }


})();
